        const auto& cfg=model_config_->get_config_json();
        const bool legacy_topology_r2347=distributed_config.tp_node_size==1&&distributed_config.tp_node_rank==0&&distributed_config.pp_size==4&&distributed_config.pp_stage>=0&&distributed_config.pp_stage<4;
        const bool global_topology_r2347=cfg.value("infinilm_kimi_global_tp_adapter",false)&&(distributed_config.tp_node_size==2||distributed_config.tp_node_size==4||(distributed_config.tp_node_size==6&&distributed_config.pp_size==1))&&distributed_config.tp_node_rank>=0&&size_t(distributed_config.tp_node_rank)<distributed_config.tp_node_size&&distributed_config.pp_size>=1&&distributed_config.pp_size<=4&&distributed_config.pp_stage>=0&&distributed_config.pp_stage<distributed_config.pp_size&&communication_group_.get_rank_info(0).tp_size==int(8*distributed_config.tp_node_size);
        if(enable_graph_compiling||pre_transpose||use_mla||kv_cache_dtype.has_value()||device_type!=infinilm::runtime::Device::Type::kHygon||local_tp_size!=8||!(legacy_topology_r2347||global_topology_r2347)||distributed_config.moe_ep_backend!="disabled"||distributed_config.moe_ep_size!=1||attention_backend_!=backends::AttentionBackend::FLASH_ATTN||!cfg.value("infinilm_text_only",false)||!cfg.value("infinilm_kimi_engine_adapter",false)||model_config_->get_dtype()!=infinilm::runtime::DataType::kBFloat16||model_config_->get_kv_quant_scheme()!=quantization::KVQuantAlgo::NONE||cfg.at("num_hidden_layers")!=93||cfg.at("hidden_size")!=7168||cfg.at("num_experts")!=896||cfg.at("num_experts_per_tok")!=16)
            throw std::invalid_argument("Kimi Engine requires actual93-layer Hygon TP8/PP4 or opt-in global TP16/32 eager BF16 text, model-owned MXFP4 routed weights, disabledEP and224/48 or288/64 pages/rows at256 width");
        kimi_native_lengths_.assign(models::kimi_native::request_capacity(cache_config_.get(),model_config_->get_config_json().value("infinilm_kimi_compact_cache_r4974",false)) + 1, 0);
    }
    workers_.reserve(local_tp_size);
    try {
        for (int r = 0; r < local_tp_size; ++r) {
            workers_.emplace_back(std::make_unique<RankWorker>(
                infinilm_config,
                communication_group_.get_rank_info(r),
                cache_config_ != nullptr ? cache_config_.get() : nullptr,
                barrier_.get(),
